<script setup>
import { onBeforeUnmount, ref } from 'vue';
const props = defineProps({ payload: { type: String, required: true } });
const state = JSON.parse(props.payload);
const publisher = state.publisher || {};
const old = state.old || {};
const errors = state.errors || {};
const csrf = document.querySelector('meta[name="csrf-token"]')?.content || '';
const preview = ref(null);
const logoFileName = ref('Choose a logo image');
let objectUrl;
function chooseLogo(event) {
    const file = event.target.files?.[0];
    if (objectUrl) URL.revokeObjectURL(objectUrl);
    objectUrl = null; preview.value = null;
    if (!file) return;
    logoFileName.value = file.name;
    if (!file.type.startsWith('image/')) { event.target.value = ''; logoFileName.value = 'Choose a logo image'; return; }
    objectUrl = URL.createObjectURL(file); preview.value = objectUrl;
}
function deletePublisher(url) {
    const send = () => { const form = document.createElement('form'); form.method='POST'; form.action=url; const token=document.createElement('input'); token.type='hidden'; token.name='_token'; token.value=csrf; const method=document.createElement('input'); method.type='hidden'; method.name='_method'; method.value='DELETE'; form.append(token,method); document.body.append(form); form.submit(); };
    if (window.Swal) window.Swal.fire({title:'Delete publisher?',text:'This action cannot be undone.',icon:'warning',showCancelButton:true,confirmButtonText:'Delete',cancelButtonText:'Cancel',reverseButtons:true}).then(result=>{if(result.isConfirmed)send();}); else if(window.confirm('Delete this publisher?'))send();
}
onBeforeUnmount(()=>{if(objectUrl)URL.revokeObjectURL(objectUrl);});
</script>

<template>
<div class="dashboard-section publishers-page">
    <template v-if="state.view==='index'">
        <section class="publishers-hero"><div class="publishers-hero-content"><div class="publishers-hero-text"><span class="publishers-hero-badge"><i class="bi bi-buildings"></i> Publishing Directory</span><h1>Publishers, beautifully organised.</h1><p>Manage publishing houses, websites, countries and publisher information from one clean workspace.</p></div><div class="publishers-hero-mark"><i class="bi bi-building"></i></div></div></section>
        <div v-if="state.success" class="alert alert-success">{{ state.success }}</div><div v-if="state.error" class="alert alert-danger">{{ state.error }}</div>
        <section class="publishers-stats"><div v-for="item in [{label:'Total Publishers',value:state.stats.total,icon:'bi-buildings',color:'stat-blue'},{label:'Active',value:state.stats.active,icon:'bi-check-circle',color:'stat-green'},{label:'Inactive',value:state.stats.inactive,icon:'bi-pause-circle',color:'stat-orange'},{label:'With Website',value:state.stats.website,icon:'bi-globe2',color:'stat-purple'}]" :key="item.label" class="publisher-stat-card"><div class="publisher-stat-icon" :class="item.color"><i class="bi" :class="item.icon"></i></div><div class="publisher-stat-content"><div class="publisher-stat-label">{{ item.label }}</div><div class="publisher-stat-value">{{ item.value }}</div></div></div></section>
        <section class="dashboard-panel publishers-panel"><div class="publishers-panel-header"><div class="publishers-heading-content"><h2 class="publishers-panel-title">Publisher directory</h2><p class="publishers-panel-description">Browse and manage all publishers registered on SecondBook.</p></div><div class="publishers-header-action"><a :href="state.urls.create" class="publishers-add-btn"><i class="bi bi-plus-lg"></i>Add Publisher</a></div></div>
            <form method="GET" :action="state.urls.index" class="publisher-filters"><div class="publisher-filter-grid"><div class="publisher-filter-group"><label class="publisher-filter-label" for="publisher-search">Search publishers</label><div class="publisher-search-field"><i class="bi bi-search"></i><input id="publisher-search" type="text" name="search" :value="state.search" class="publisher-input" placeholder="Search by publisher name..." autocomplete="off"></div></div><div class="publisher-filter-actions"><button type="submit" class="publisher-filter-btn"><i class="bi bi-funnel"></i>Filter</button><a v-if="state.search" :href="state.urls.index" class="publisher-secondary-btn"><i class="bi bi-x-lg"></i>Clear</a></div></div></form>
            <div class="publishers-table-wrap"><table class="publishers-table"><thead><tr><th class="publishers-col-id">#</th><th class="publishers-col-publisher">Publisher</th><th class="publishers-col-country">Country</th><th class="publishers-col-website">Website</th><th class="publishers-col-description">Description</th><th class="publishers-col-status">Status</th><th class="publishers-col-date">Created</th><th class="publishers-col-actions">Actions</th></tr></thead><tbody>
                <tr v-for="item in state.publishers" :key="item.id"><td>#{{ item.id }}</td><td><div class="publisher-item-cell"><div class="publisher-logo-wrapper"><img v-if="item.logo" :src="item.logo" :alt="item.name" class="publisher-logo-thumb" loading="lazy"><div v-else class="publisher-logo-placeholder"><i class="bi bi-building"></i></div></div><div><strong>{{ item.name }}</strong></div></div></td><td>{{ item.country || '—' }}</td><td><a v-if="item.website" :href="item.website" target="_blank" rel="noopener noreferrer">{{ item.website }}</a><span v-else>—</span></td><td>{{ item.description ? (item.description.length>70 ? `${item.description.slice(0,67)}...` : item.description) : '—' }}</td><td><span class="publisher-status-pill" :class="item.status?'publisher-status-active':'publisher-status-inactive'">{{ item.status?'Active':'Inactive' }}</span></td><td>{{ item.created_at || '—' }}</td><td><div class="publisher-actions"><a :href="item.show_url" class="publisher-action-btn publisher-view-btn" title="View Publisher"><i class="bi bi-eye"></i></a><form :action="item.status_url" method="POST" class="publisher-status-form"><input type="hidden" name="_token" :value="csrf"><input type="hidden" name="_method" value="PATCH"><button type="submit" class="publisher-status-btn" :class="item.status?'deactivate':'activate'" :title="item.status?'Deactivate':'Activate'"><i class="bi" :class="item.status?'bi-pause-circle':'bi-check-circle'"></i></button></form><a :href="item.edit_url" class="publisher-action-btn publisher-edit-btn" title="Edit Publisher"><i class="bi bi-pencil"></i></a><button type="button" class="publisher-action-btn publisher-delete-btn" title="Delete Publisher" @click="deletePublisher(item.delete_url)"><i class="bi bi-trash"></i></button></div></td></tr>
                <tr v-if="!state.publishers.length"><td colspan="8"><div class="publisher-empty-state"><i class="bi bi-buildings"></i><h5>No publishers found</h5><p>Try adjusting your search or add a publisher.</p><a :href="state.urls.create" class="publishers-add-btn">Add Publisher</a></div></td></tr>
            </tbody></table></div>
            <div v-if="state.pagination.last_page>1" class="publishers-pagination"><div>Showing <strong>{{state.pagination.first}}</strong> to <strong>{{state.pagination.last}}</strong> of <strong>{{state.pagination.total}}</strong> publishers</div><nav class="publishers-pagination-pages"><a class="publisher-page" :class="{disabled:!state.pagination.previous}" :href="state.pagination.previous||undefined">‹</a><a v-for="(url,page) in state.pagination.pages" :key="page" class="publisher-page" :class="{active:Number(page)===Number(state.pagination.current)}" :href="url">{{page}}</a><a class="publisher-page" :class="{disabled:!state.pagination.next}" :href="state.pagination.next||undefined">›</a></nav></div>
        </section>
    </template>

    <template v-else-if="state.view==='create'||state.view==='edit'">
        <section class="publishers-hero publishers-hero-compact"><div class="publishers-hero-content"><div class="publishers-hero-text"><span class="publishers-hero-badge"><i class="bi bi-building"></i>{{state.view==='create'?'New Publisher':'Publisher Management'}}</span><h1>{{state.view==='create'?'Add Publisher':'Edit Publisher'}}</h1><p>{{state.view==='create'?'Create a publisher profile and add its public details.':'Update the publisher information and keep the directory accurate and up to date.'}}</p></div><div class="publishers-hero-mark"><i class="bi bi-building-gear"></i></div></div></section>
        <section class="dashboard-panel publishers-panel"><div class="publishers-panel-header"><div class="publishers-heading-content"><h2 class="publishers-panel-title">{{state.view==='create'?'Add publisher information':'Edit publisher information'}}</h2><p class="publishers-panel-description">Manage the publisher’s name, logo, country, website, description and status.</p></div><div class="publishers-header-action"><a :href="state.urls.index" class="publisher-secondary-btn"><i class="bi bi-arrow-left"></i>Back to Publishers</a></div></div>
            <form :action="state.view==='create'?state.urls.store:state.urls.update" method="POST" enctype="multipart/form-data"><input type="hidden" name="_token" :value="csrf"><input v-if="state.view==='edit'" type="hidden" name="_method" value="PUT"><div class="publisher-form-layout"><div class="publisher-form-main"><div v-if="Object.keys(errors).length" class="publisher-form-alert"><strong>Please correct the following errors:</strong><ul><template v-for="(messages,key) in errors" :key="key"><li v-for="error in messages" :key="error">{{error}}</li></template></ul></div><div class="publisher-form-grid">
                <div class="publisher-field publisher-field-full"><label for="publisher-name" class="publisher-field-label">Publisher Name <span class="text-danger">*</span></label><input id="publisher-name" name="name" class="publisher-input" :class="{'is-invalid':errors.name}" :value="old.name" maxlength="255" required placeholder="Enter publisher name"><div v-for="error in errors.name" :key="error" class="publisher-field-error">{{error}}</div></div>
                <div class="publisher-field"><label for="publisher-country" class="publisher-field-label">Country</label><input id="publisher-country" name="country" class="publisher-input" :class="{'is-invalid':errors.country}" :value="old.country" maxlength="120" placeholder="Enter country"><div v-for="error in errors.country" :key="error" class="publisher-field-error">{{error}}</div></div>
                <div class="publisher-field"><label for="publisher-website" class="publisher-field-label">Website</label><input id="publisher-website" type="url" name="website" class="publisher-input" :class="{'is-invalid':errors.website}" :value="old.website" maxlength="255" placeholder="https://example.com"><div v-for="error in errors.website" :key="error" class="publisher-field-error">{{error}}</div></div>
                <div class="publisher-field publisher-field-full"><label for="publisher-description" class="publisher-field-label">Description</label><textarea id="publisher-description" name="description" rows="5" class="publisher-textarea" :class="{'is-invalid':errors.description}" :value="old.description" maxlength="2000" placeholder="Write a short description about this publisher..."></textarea><div v-for="error in errors.description" :key="error" class="publisher-field-error">{{error}}</div></div>
            </div><div class="publisher-status-toggle"><input type="checkbox" name="status" value="1" id="publisher-status" :checked="['1',1,true].includes(old.status)"><label for="publisher-status">Active publisher</label></div><div class="publisher-form-actions"><button type="submit" class="publisher-form-submit"><i class="bi bi-check2-circle"></i>{{state.view==='create'?'Save Publisher':'Update Publisher'}}</button><a :href="state.urls.index" class="publisher-secondary-btn">Cancel</a></div></div>
            <aside class="publisher-form-side"><div class="dashboard-panel publisher-logo-card"><h5>Publisher logo</h5><div class="publisher-logo-preview"><div v-if="preview||publisher.logo" class="publisher-logo-preview-image"><img :src="preview||publisher.logo" alt="Publisher logo preview"></div><div v-else class="publisher-logo-placeholder"><i class="bi bi-building"></i></div></div><div class="publisher-file-upload"><input id="publisher-logo" type="file" name="logo" accept="image/png,image/jpeg,image/jpg,image/webp" class="publisher-file-input" @change="chooseLogo"><label for="publisher-logo" class="publisher-file-label"><i class="bi bi-cloud-arrow-up"></i><span class="publisher-file-title">{{state.view==='edit'?'Replace logo':'Upload logo'}}</span><span class="publisher-file-name">{{logoFileName}}</span></label></div><div v-for="error in errors.logo" :key="error" class="publisher-field-error">{{error}}</div></div></aside></div></form>
        </section>
    </template>

    <template v-else>
        <section class="publishers-hero publishers-hero-compact"><div class="publishers-hero-content"><div class="publishers-hero-text"><span class="publishers-hero-badge"><i class="bi bi-building"></i>Publisher Details</span><h1>{{publisher.name}}</h1><p>Review publisher information, status and publishing details.</p></div><div class="publishers-hero-mark"><i class="bi bi-building-check"></i></div></div></section>
        <section class="dashboard-panel publishers-panel"><div class="publishers-panel-header"><div class="publishers-heading-content"><h2 class="publishers-panel-title">Publisher information</h2><p class="publishers-panel-description">Complete details for this publisher.</p></div><div class="publishers-header-action"><a :href="state.urls.index" class="publisher-secondary-btn"><i class="bi bi-arrow-left"></i>Back to Publishers</a><a :href="state.urls.edit" class="publisher-secondary-btn"><i class="bi bi-pencil"></i>Edit Publisher</a></div></div>
            <div class="publisher-detail-layout"><aside class="publisher-detail-sidebar"><div class="publisher-detail-logo"><img v-if="publisher.logo" :src="publisher.logo" :alt="publisher.name"><div v-else class="publisher-logo-placeholder"><i class="bi bi-building"></i></div></div><h3 class="publisher-detail-name">{{publisher.name}}</h3><p class="publisher-detail-country">{{publisher.country||'Country not specified'}}</p><span class="publisher-status-pill" :class="publisher.status?'publisher-status-active':'publisher-status-inactive'">{{publisher.status?'Active':'Inactive'}}</span></aside><div class="publisher-detail-grid"><div class="publisher-detail-item"><span>Publisher ID</span><strong>#{{publisher.id}}</strong></div><div class="publisher-detail-item"><span>Name</span><strong>{{publisher.name}}</strong></div><div class="publisher-detail-item"><span>Country</span><strong>{{publisher.country||'—'}}</strong></div><div class="publisher-detail-item"><span>Website</span><a v-if="publisher.website" :href="publisher.website" target="_blank" rel="noopener noreferrer">{{publisher.website}}</a><strong v-else>—</strong></div><div class="publisher-detail-item"><span>Status</span><strong>{{publisher.status?'Active':'Inactive'}}</strong></div><div class="publisher-detail-item"><span>Created</span><strong>{{publisher.created}}</strong></div><div class="publisher-detail-item"><span>Last updated</span><strong>{{publisher.updated}}</strong></div><div class="publisher-detail-item publisher-detail-item-full"><span>Description</span><p>{{publisher.description||'No description has been added.'}}</p></div></div></div>
        </section>
    </template>
</div>
</template>
